class Solution {
  public int maximumLength(int[] nums, int k) {
    int n = nums.length, answer = 1;
    int[][] dp = new int[n][k + 1];
    for (int i = 0; i < n; i++) {
      for (int changes = 0; changes <= k; changes++) {
        dp[i][changes] = 1;
        for (int j = 0; j < i; j++) {
          int extra = nums[i] == nums[j] ? 0 : 1;
          if (extra <= changes)
            dp[i][changes] = Math.max(dp[i][changes], dp[j][changes - extra] + 1);
        }
        answer = Math.max(answer, dp[i][changes]);
      }
    }
    return answer;
  }
}
